    /// signal NSTextField.control-text-did-change (notification): NSControl.h: NSControlTextDidChangeNotification, object = the control, posted for user edits (KVO does not fire for typing). Observed on the default center, so the delegate slot stays free. JS gets the new text as the first argument.
    pub fn signal_nstextfield_control_text_did_change() {
        let h = Harness::shared();
        let o = h.create("text-field");
        h.take_events();
        h.listen(o, "control-text-did-change", true).unwrap();
        h.post_notification(o, "NSControlTextDidChangeNotification");
        let ev = h.take_events();
        assert!(ev.iter().any(|e| e.0 == o && e.1 == "control-text-did-change" && e.2.len() == 1), "delivered: {ev:?}");
        h.listen(o, "control-text-did-change", false).unwrap();
        h.post_notification(o, "NSControlTextDidChangeNotification");
        assert!(h.take_events().iter().all(|e| e.1 != "control-text-did-change"), "not delivered after listen off");
        h.destroy(o);
    }

