    /// slot NSView.subviews: NSView.h: addSubview:, addSubview:positioned:relativeTo: (NSWindowBelow puts the view below `relativeTo`), removeFromSuperview; the superview retains its subviews
    pub fn slot_nsview_subviews() {
        let h = Harness::shared();
        let p = h.create("view");
        let a = h.create("view");
        let b = h.create("view");
        h.insert(p, a, None, Some("subviews")).unwrap();
        h.insert(p, b, Some(a), Some("subviews")).unwrap();
        assert_eq!(h.native_list(p, "subviews"), vec![h.obj(b), h.obj(a)], "b inserted before a");
        assert!(h.superview(a) == Some(h.obj(p)), "a is a subview");
        h.remove(p, b).unwrap();
        assert!(h.superview(b).is_none(), "removed child is detached");
        assert_eq!(h.native_list(p, "subviews"), vec![h.obj(a)]);
        h.remove(p, b).unwrap_err();
        h.insert(p, b, None, Some("subviews")).unwrap();
        assert_eq!(h.native_list(p, "subviews"), vec![h.obj(a), h.obj(b)], "re-inserted at the end");
        h.destroy(p);
        h.destroy(a);
        h.destroy(b);
    }

