    /// Table-driven: a notification signal is delivered while listened to and not after listen off
    /// (the notification is posted by the test: delivery, not native causation).
    pub fn signal_row(i: usize) {
        let r = &SIGNAL_ROWS[i];
        let h = Harness::shared();
        let _g = h.case_guard();
        let o = h.create(r.tag);
        h.take_events();
        h.listen(o, r.signal, true).unwrap();
        h.post_notification(o, r.notification);
        let ev = h.take_events();
        assert!(ev.iter().any(|e| e.0 == o && e.1 == r.signal && e.2.len() == r.nargs), "delivered: {ev:?}");
        h.listen(o, r.signal, false).unwrap();
        h.post_notification(o, r.notification);
        assert!(h.take_events().iter().all(|e| e.1 != r.signal), "not delivered after listen off");
        h.destroy(o);
    }

